BEGIN;
CREATE SCHEMA IF NOT EXISTS iccdmt;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE iccdmt.users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,password_hash text NOT NULL,role text NOT NULL DEFAULT 'public' CHECK(role IN('public','student','ta','professor')),must_change_password boolean NOT NULL DEFAULT false,onboarding_complete boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE iccdmt.profiles(user_id uuid PRIMARY KEY REFERENCES iccdmt.users ON DELETE CASCADE,display_name text NOT NULL,avatar_url text,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE iccdmt.cycles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),label text NOT NULL,starts_at timestamptz,ends_at timestamptz,class_count int NOT NULL DEFAULT 3 CHECK(class_count>0));
CREATE TABLE iccdmt.lectures(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),cycle_id uuid REFERENCES iccdmt.cycles,title jsonb NOT NULL,summary jsonb NOT NULL,week_no int,lecture_no int,published boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),CHECK(title ?& ARRAY['ko','en','rw']),CHECK(summary ?& ARRAY['ko','en','rw']));
CREATE TABLE iccdmt.lecture_blocks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),lecture_id uuid NOT NULL REFERENCES iccdmt.lectures ON DELETE CASCADE,kind text NOT NULL,position int NOT NULL,payload jsonb NOT NULL,hidden boolean NOT NULL DEFAULT false,UNIQUE(lecture_id,position));
CREATE TABLE iccdmt.assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),cycle_id uuid REFERENCES iccdmt.cycles,title jsonb NOT NULL,description jsonb NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','scheduled','open','submission_closed','professor_approval','peer_review_open','peer_review_closed','professor_review','completed','archived')),due_at timestamptz,review_starts_at timestamptz,review_ends_at timestamptz,peer_feedback_required int NOT NULL DEFAULT 3 CHECK(peer_feedback_required>=0),best_work_required int NOT NULL DEFAULT 3 CHECK(best_work_required=3),CHECK(title ?& ARRAY['ko','en','rw']),CHECK(description ?& ARRAY['ko','en','rw']));
CREATE TABLE iccdmt.submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),assignment_id uuid NOT NULL REFERENCES iccdmt.assignments ON DELETE CASCADE,author_id uuid NOT NULL REFERENCES iccdmt.users,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','submitted','changes_requested','approved','excluded','peer_reviewed','graded')),title text NOT NULL DEFAULT '',body_md text NOT NULL DEFAULT '',submitted_at timestamptz,final_score numeric,professor_feedback text,UNIQUE(assignment_id,author_id));
CREATE TABLE iccdmt.peer_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),assignment_id uuid NOT NULL REFERENCES iccdmt.assignments ON DELETE CASCADE,submission_id uuid NOT NULL REFERENCES iccdmt.submissions ON DELETE CASCADE,reviewer_id uuid NOT NULL REFERENCES iccdmt.users,feedback text NOT NULL,score numeric,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(submission_id,reviewer_id));
CREATE TABLE iccdmt.best_work_votes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),assignment_id uuid NOT NULL REFERENCES iccdmt.assignments ON DELETE CASCADE,submission_id uuid NOT NULL REFERENCES iccdmt.submissions ON DELETE CASCADE,voter_id uuid NOT NULL REFERENCES iccdmt.users,author_id uuid NOT NULL REFERENCES iccdmt.users,cycle_id uuid NOT NULL REFERENCES iccdmt.cycles,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(assignment_id,voter_id,submission_id),UNIQUE(cycle_id,voter_id,author_id));
CREATE TABLE iccdmt.hall_of_fame(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),submission_id uuid UNIQUE NOT NULL REFERENCES iccdmt.submissions ON DELETE CASCADE,selected_by uuid NOT NULL REFERENCES iccdmt.users,selected_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE iccdmt.portfolio_frames(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),assignment_id uuid UNIQUE REFERENCES iccdmt.assignments ON DELETE SET NULL,label jsonb NOT NULL,position int NOT NULL,active boolean NOT NULL DEFAULT true,CHECK(label ?& ARRAY['ko','en','rw']));
CREATE TABLE iccdmt.audit_log(id bigserial PRIMARY KEY,actor_id uuid REFERENCES iccdmt.users,action text NOT NULL,entity_type text NOT NULL,entity_id uuid,payload jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION iccdmt.guard_review() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE a text; author uuid; BEGIN SELECT status INTO a FROM iccdmt.assignments WHERE id=NEW.assignment_id; SELECT author_id INTO author FROM iccdmt.submissions WHERE id=NEW.submission_id AND assignment_id=NEW.assignment_id AND status='approved'; IF a<>'peer_review_open' OR author IS NULL OR author=NEW.reviewer_id THEN RAISE EXCEPTION 'peer review not permitted'; END IF; RETURN NEW; END $$;
CREATE TRIGGER peer_review_guard BEFORE INSERT OR UPDATE ON iccdmt.peer_reviews FOR EACH ROW EXECUTE FUNCTION iccdmt.guard_review();
CREATE OR REPLACE FUNCTION iccdmt.guard_vote() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE a text; author uuid; cnt int; BEGIN SELECT status INTO a FROM iccdmt.assignments WHERE id=NEW.assignment_id; SELECT author_id INTO author FROM iccdmt.submissions WHERE id=NEW.submission_id AND assignment_id=NEW.assignment_id AND status='approved'; IF a<>'peer_review_open' OR author IS NULL OR author=NEW.voter_id OR author<>NEW.author_id THEN RAISE EXCEPTION 'best work vote not permitted'; END IF; SELECT count(*) INTO cnt FROM iccdmt.best_work_votes WHERE assignment_id=NEW.assignment_id AND voter_id=NEW.voter_id AND id<>NEW.id; IF cnt>=3 THEN RAISE EXCEPTION 'maximum three best work votes'; END IF; RETURN NEW; END $$;
CREATE TRIGGER best_work_guard BEFORE INSERT OR UPDATE ON iccdmt.best_work_votes FOR EACH ROW EXECUTE FUNCTION iccdmt.guard_vote();
COMMIT;
